]);

const EXT_LANG = {
  ".ts": "ts",
  ".tsx": "tsx",
  ".js": "js",
  ".jsx": "jsx",
  ".mjs": "js",
  ".cjs": "js",
  ".json": "json",
  ".yml": "yaml",
  ".yaml": "yaml",
  ".md": "md",
  ".txt": "txt",
  ".css": "css",
