  ".less": "less",
  ".graphql": "graphql",
  ".gql": "graphql",
  ".proto": "proto",
  ".sql": "sql",
  ".xml": "xml",
};

const EXT_MEDIA = {
  ".ts": "text/typescript",
  ".tsx": "text/typescript",
  ".js": "text/javascript",
  ".jsx": "text/javascript",
  ".mjs": "text/javascript",
  ".cjs": "text/javascript",
  ".json": "application/json",
  ".jsonc": "application/json",
  ".yml": "text/yaml",
  ".yaml": "text/yaml",
  ".md": "text/markdown",
  ".txt": "text/plain",
  ".css": "text/css",
  ".scss": "text/x-scss",
  ".less": "text/x-less",
